/**#command
name: /addstock_id
answer: 
keyboard: 
parse_mode: markdown
aliases: 
allow_only_group: false
need_reply: false
case_insensitive: false
is_web: 0
#command**/

try {
  var adminId = "7088682169";
  if (String(chat.chatid) !== adminId) return;

  // Agar message khali hai
  if (!message) {
    Bot.sendMessage("❌ Format: <code>/addstock_id category_name email|password</code>", {parse_mode: "HTML"});
    return;
  }

  // Pura text line-by-line split karein (Bulk upload support ke liye)
  var lines = message.split("\n");
  var categories = Bot.getProperty("ff_categories") || {};

  var pendingStock = {}; 
  var totalAdded = 0;
  var reportMessage = "⚡ <b>Stock Loaded Successfully!</b>\n\n";

  for (var i = 0; i < lines.length; i++) {
    var currentLine = lines[i].trim();
    if (!currentLine) continue;

    // Command hatayein agar pehli line me ho
    if (currentLine.toLowerCase().indexOf("/addstock_id") === 0) {
      currentLine = currentLine.substring(12).trim(); // "/addstock_id" ki length 12 hai
    }

    if (!currentLine) continue;

    // Category aur account data ke beech ka space dhoondhein
    var spaceIndex = currentLine.indexOf(" ");
    if (spaceIndex === -1) continue;

    var alias = currentLine.substring(0, spaceIndex).toLowerCase().trim(); 
    var credential = currentLine.substring(spaceIndex + 1).trim(); // email|pass

    // Agar credential me "|" nahi hai toh line skip karein (Valid format check)
    if (credential.indexOf("|") === -1) continue;

    var finalSlug = "";

    // 1. Exact Category Slug Check
    if (categories[alias]) {
      finalSlug = alias;
    } else {
      // 2. Contains Slug Check or Name Match (Jaise 'lodu' ya 'fb')
      for (var key in categories) {
        var cleanKey = key.toLowerCase();
        var catName = categories[key].name ? categories[key].name.toLowerCase() : "";

        if (cleanKey.indexOf(alias) !== -1 || alias.indexOf(cleanKey) !== -1 ||
            catName.indexOf(alias) !== -1 || alias.indexOf(catName) !== -1) {
          finalSlug = key;
          break;
        }
      }
    }

    // Queue data if category found
    if (finalSlug !== "") {
      if (!pendingStock[finalSlug]) {
        pendingStock[finalSlug] = [];
      }
      pendingStock[finalSlug].push(credential);
      totalAdded++;
    }
  }

  // Database me save karein
  if (totalAdded > 0) {
    for (var slug in pendingStock) {
      var currentStock = Bot.getProperty("ff_stock_" + slug) || [];
      if (!Array.isArray(currentStock)) currentStock = [];

      var newAccounts = pendingStock[slug];
      for (var j = 0; j < newAccounts.length; j++) {
        currentStock.push(newAccounts[j]);
      }

      Bot.setProperty("ff_stock_" + slug, currentStock, "json");

      var catName = categories[slug] && categories[slug].name ? categories[slug].name : slug.toUpperCase();
      reportMessage += "• <code>" + newAccounts.length + " accounts</code> ➔ <b>" + catName + "</b>\n";
    }

    Bot.sendMessage(reportMessage, {parse_mode: "HTML"});
  } else {
    Bot.sendMessage("❌ <b>Stock Add Nahi Hua!</b>\n\nKyu nahi hua?\n1. <code>LODU</code> naam ki category system me nahi bani hai.\n2. Aapne account ke beech me <code>|</code> nahi lagaya.\n\n<b>Sahi Format:</b>\n<code>/addstock_id lodu jajaj@gmail.com|Sam72@</code>", {parse_mode: "HTML"});
  }

} catch(e) {
  Bot.sendMessage("Error: " + e.message);
}

/**#command
name: /check_users
answer: 
keyboard: 
parse_mode: markdown
aliases: 
allow_only_group: false
need_reply: false
case_insensitive: false
is_web: 0
#command**/

// =========================================================
// 👥 COMMAND: /check_users
// STATUS: 100% OPERATIONAL & ANTI-CRASH CHUNK SYSTEM
// =========================================================

try {
  var adminId = "7088682169"; // Aapki Admin ID

  // Strict Admin Validation
  if (String(chat.chatid) !== adminId) {
    Bot.sendMessage("❌ Access Denied: Sirf Owner hi user database dekh sakta hai.");
    return;
  }

  // Fetch users array safely
  var userList = Bot.getProperty("all_users_list") || [];
  if (!Array.isArray(userList)) { userList = []; }

  if (userList.length === 0) {
    Bot.sendMessage("⚠️ <b>Database Empty:</b> Bot mein abhi tak koi bhi user register nahi hua hai.", { parse_mode: "HTML" });
    return;
  }

  var header = "<blockquote><b>👥 TOTAL REGISTERED USERS LIST</b>\n\n" +
               "📊 <b>Total Growth Node:</b> <code>" + userList.length + " Active Users</code></blockquote>\n" +
               "━━━━━━━━━━━━━━━━━━━━━━━━━━\n\n";

  var bodyText = "";

  // Loop through all users and format
  for (var i = 0; i < userList.length; i++) {
    var userLine = "<b>[" + (i + 1) + "]</b> ID: <code>" + userList[i] + "</code>\n";

    // Memory and boundary protection: Split messages if character count exceeds 3500
    if ((header + bodyText + userLine).length > 3500) {
      Bot.sendMessage(header + bodyText, { parse_mode: "HTML" });
      header = ""; // Clear header for subsequent chunks
      bodyText = ""; // Reset temporary storage buffer
    }
    bodyText += userLine;
  }

  // Print final remaining chunk safely
  if (bodyText.trim() !== "") {
    Bot.sendMessage(header + bodyText + "\n━━━━━━━━━━━━━━━━━━━━━━━━━━", { parse_mode: "HTML" });
  }

} catch (err) {
  Bot.sendMessage("🛑 <b>User Audit Error:</b> <code>" + err.message + "</code>", { parse_mode: "HTML" });
}

/**#command
name: /addkey
answer: 
keyboard: 
parse_mode: markdown
aliases: 
allow_only_group: false
need_reply: false
case_insensitive: false
is_web: 0
#command**/

try {
  var adminId = "7088682169";
  if (String(chat.chatid) !== adminId) {
    Bot.sendMessage("❌ You are not the admin!");
    return;
  }

  if (!params) {
    Bot.sendMessage("⚠️ *Format:* `/addkey PRODUCT NAME | DAYS | KEY1`\n`KEY2`\n`KEY3` (Line-by-line)", { parse_mode: "Markdown" });
    return;
  }

  var lines = params.split("\n");
  var firstLineParts = lines[0].split("|");

  if (firstLineParts.length < 3) {
    Bot.sendMessage("⚠️ *Galat Format!*\nPehli line me `Product Name | Days | Key` hona chahiye.", { parse_mode: "Markdown" });
    return;
  }

  // 1. Inputs ko clean aur trim karna
  var pName = firstLineParts[0].trim().toLowerCase();
  var pDays = firstLineParts[1].trim(); 

  var pDaysClean = pDays.includes("_Day") ? pDays : pDays + "_Day";
  var pDaysNumOnly = pDays.replace("_Day", "").trim(); 

  var keysToAdd = [];
  keysToAdd.push(firstLineParts[2].trim());

  for (var l = 1; l < lines.length; l++) {
    var currentLineKey = lines[l].trim();
    if (currentLineKey !== "") {
      keysToAdd.push(currentLineKey);
    }
  }

  // 2. Products fetching
  var productList = Bot.getProperty("stored_products") || [];
  var prodIdx = -1;
  var planIdx = -1;
  var exactProdName = firstLineParts[0].trim(); // Fallback name

  // Soft loop matching (Case insensitive)
  for (var i = 0; i < productList.length; i++) {
    if (productList[i].name.trim().toLowerCase() === pName) {
      prodIdx = i;
      exactProdName = productList[i].name.trim();
      break;
    }
  }

  // FORCE CORRECTION: Agar index loop se na mile to handle anyway
  if (prodIdx === -1) {
    Bot.sendMessage("⚠️ Product *" + exactProdName + "* lists me nahi mila, par system dynamic key store bypass generate kar raha hai...", { parse_mode: "Markdown" });
  } else {
    var plans = productList[prodIdx].plans || [];
    for (var j = 0; j < plans.length; j++) {
      if (String(plans[j].days).trim() === pDaysNumOnly) {
        planIdx = j;
        break;
      }
    }
  }

  // 3. Dual-pipeline saving mechanics
  var stockKeyText = "stock_" + exactProdName + "_" + pDaysClean;
  var currentStock = Bot.getProperty(stockKeyText) || [];

  // Array merging
  var updatedStock = currentStock.concat(keysToAdd);
  Bot.setProperty(stockKeyText, updatedStock, "json");

  // Agar structured index match hua hai to us pipeline ko bhi update karein
  if (prodIdx !== -1 && planIdx !== -1) {
    var stockKeyIndex = "stock_" + prodIdx + "_" + planIdx;
    Bot.setProperty(stockKeyIndex, updatedStock, "json");
  }

  // 4. GUARANTEED SUCCESS CONFIRMATION MESSAGE
  var successMsg = "<blockquote><b>📦 STOCK UPDATED SUCCESSFULLY</b>\n\n" +
                   "• <b>Product:</b> <code>" + exactProdName + "</code>\n" +
                   "• <b>Plan:</b> <code>" + pDaysClean + "</code>\n" +
                   "• <b>Added Keys:</b> <code>" + keysToAdd.length + " Keys</code>\n" +
                   "• <b>Total Stock Now:</b> <code>" + updatedStock.length + " Keys available</code></blockquote>";

  Bot.sendMessage(successMsg, { parse_mode: "HTML" });

} catch (err) {
  Bot.sendMessage("⚠️ System Error: " + err.message);
}

