                  "<tg-emoji emoji-id='5346024644635804737'>🔰</tg-emoji> You Are Now A Reseller.\n" +
                  "Check Your Discounted Store /start To Check Now<tg-emoji emoji-id='6298298582982199311'>💰</tg-emoji></blockquote>";

  Api.sendMessage({
    chat_id: targetId,
